logger = logging.getLogger(__name__)

INTERPOLATION_METHODS = ("linear", "lower", "higher", "nearest", "midpoint")
INTERPOLATION_CODES = {name: code for code, name in enumerate(INTERPOLATION_METHODS)}
MAX_BITONIC_SIZE = 2048
# Lower and upper bounds on the reduction length for row-batch rank selection (pairs kernel):
# - Lower bound: shorter rows stay on the bitonic path (tl.sort overhead on small blocks is negligible, and tiny levels
# like (1,) are already at the launch floor).
# - Upper bound 2048: the (BLOCK_R, BLOCK_M) matrix with BLOCK_M=next_pow2(reduction_size) is of the same
#   origin as the old select kernel; BLOCK_M >= 4096 makes gcu-compiler-opt crash on a ShapedType::getNumElements
#   assertion (int overflow), so rows in (2048, 4096] do not use this kernel (switch to sort+gather, fixing the latent
# compiler crash of the old select gate
#   reduction_size<=4096 on that interval).
MIN_SELECT_SIZE = 8
MAX_SELECT_SIZE = 2048
# For a python float scalar q, the pairs-path lower bound drops to 1: the scalar bitonic/gather path pays
# a H2D on every call via torch.tensor(q) (~50-90µs host floor), whereas pairs can pass the scalar argument directly,
# and on tiny reductions (BLOCK_M<8) even 32 counting rounds take only ~25µs, making it ~2x faster; tensor q (including
# 0-dim)
# has no H2D issue, so tiny reductions still use bitonic (the kernel is cheaper).
MIN_SELECT_SIZE_SCALAR = 1
MAX_REDUCTION_SIZE = 1 << 24


@libentry()
@triton.jit
def _sort_keys_kernel(inp, keys, n_elements, BLOCK_SIZE: tl.constexpr):
    offsets = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    values = tl.load(inp + offsets, mask=mask)
    tl.store(
        keys + offsets, tl.where(values == values, values, float("nan")), mask=mask
    )


@libentry()
@triton.jit
def _nanquantile_bitonic_kernel(
    inp,
    q,
    out,
    reduction_size,
    q_size,
    BLOCK_M: tl.constexpr,
    BLOCK_Q: tl.constexpr,
    interpolation: tl.constexpr,
):
    row = ext.program_id(0)
    compute_type = inp.dtype.element_ty
    cols = tl.arange(0, BLOCK_M)
    valid_col = cols < reduction_size
    values = tl.load(inp + row * reduction_size + cols, mask=valid_col, other=0.0)
    valid_value = valid_col & (values == values)
    sortable = tl.where(valid_value, values, float("inf"))
    if BLOCK_M == 1:
        sorted_values = sortable
    else:
        sorted_values = tl.sort(sortable, descending=False)
    valid_count = tl.sum(valid_value.to(tl.int32), axis=0)

    q_offsets = ext.program_id(1) * BLOCK_Q + tl.arange(0, BLOCK_Q)
    valid_q = q_offsets < q_size
    q_values = tl.load(q + q_offsets, mask=valid_q, other=0.0).to(compute_type)
    last_valid = tl.maximum(valid_count - 1, 0).to(compute_type)
    ranks = q_values * last_valid
    lower = tl.floor(ranks).to(tl.int32)
    upper = tl.ceil(ranks).to(tl.int32)
    value_offsets = tl.arange(0, BLOCK_M)[:, None]
    lower_values = tl.max(
        tl.where(
            value_offsets == lower[None, :], sorted_values[:, None], float("-inf")
        ),
        axis=0,
    )
    upper_values = tl.max(
        tl.where(
            value_offsets == upper[None, :], sorted_values[:, None], float("-inf")
        ),
        axis=0,
    )

    if interpolation == 0:
        result = lower_values + (upper_values - lower_values) * (ranks - lower)
    elif interpolation == 1:
        result = lower_values
    elif interpolation == 2:
        result = upper_values
    elif interpolation == 3:
        rounded = tl_extra_shim.rint(ranks).to(tl.int32)
        result = tl.where(rounded == upper, upper_values, lower_values)
    else:
        result = lower_values + (upper_values - lower_values) * 0.5

    result = tl.where(valid_count == 0, float("nan"), result)
    tl.store(out + row * q_size + q_offsets, result, mask=valid_q)


@libentry()
@triton.jit
def _nanquantile_pairs_kernel(
    inp,
    q,
    out,
    n_pairs,
    n_rows,
    reduction_size,
    q_size,
    q_scalar,
    BLOCK_M: tl.constexpr,
    BLOCK_R: tl.constexpr,
    Q_SCALAR: tl.constexpr,
    interpolation: tl.constexpr,
):
    """Row-batch bit-exact rank selection: flatten (row, q) pairs into the lane axis in row-major
    order, advancing BLOCK_R independent 32-round count bisections at once with a (BLOCK_R, BLOCK_M) matrix.

    A cross-lane reduce on GCU (axis-reduce materialized to DSM) costs ~0.7-1.3us and is largely
    independent of matrix width; the old select kernel handled one row per program (a 1-D input
    even got a single program), so the 32-round serial reduce tax could not be amortized and the
    48 SPs sat mostly idle. This kernel spreads the same tax over BLOCK_R (row, q) pairs:

    2-D and 6-9x on 1-D, since the row count no longer limits parallelism. Key mapping matches
    the old select kernel: float32 values become IEEE754-bitwise monotonic int32 keys (positive
    key = bits, negative key = bits ^ 0x7FFFFFFF), and NaN is excluded from the count via
    values == values. The upper value is the smallest key strictly greater than lower_key (one
    masked-min, replacing a second bisection); the midpoint uses the overflow-free int32 formula
    (lo & hi) + ((lo ^ hi) >> 1), with no int64 vector chain at all.
    """
    pid = ext.program_id(0)
    pair_ids = pid * BLOCK_R + tl.arange(0, BLOCK_R)
    pair_valid = pair_ids < n_pairs
    pair_rows = pair_ids // q_size
    pair_qs = pair_ids - pair_rows * q_size
    rows = tl.where(pair_valid, pair_rows, 0)
    row_base = rows.to(tl.int64) * reduction_size
    cols = tl.arange(0, BLOCK_M)
    in_range = cols < reduction_size

    values = tl.load(
        inp + row_base[:, None] + cols[None, :],
        mask=pair_valid[:, None] & in_range[None, :],
        other=0.0,
    )
    valid = (values == values) & pair_valid[:, None] & in_range[None, :]
    valid_count = tl.sum(valid.to(tl.int32), axis=1)
    bits = values.to(tl.int32, bitcast=True)
    keys = tl.where(bits < 0, bits ^ 0x7FFFFFFF, bits)

    # Q_SCALAR: a python float scalar q goes directly as a kernel scalar argument, avoiding creation of a device tensor
    # on the host
    # (one H2D copy per call is about 50-90µs, the host floor for the scalar variant)
    if Q_SCALAR:
        q_values = tl.zeros((BLOCK_R,), dtype=tl.float32) + q_scalar
    else:
        q_values = tl.load(q + pair_qs, mask=pair_valid, other=0.0).to(tl.float32)
    last_valid = tl.maximum(valid_count - 1, 0).to(tl.float32)
    ranks = q_values * last_valid
    lower_rank = tl.floor(ranks).to(tl.int32)
    upper_rank = tl.ceil(ranks).to(tl.int32)

    lo = tl.full((BLOCK_R,), -2147483648, dtype=tl.int32)
    hi = tl.full((BLOCK_R,), 2147483647, dtype=tl.int32)
    target = lower_rank + 1
    for _ in tl.static_range(32):
        mid = (lo & hi) + ((lo ^ hi) >> 1)
        cnt = tl.sum(tl.where(valid & (keys <= mid[:, None]), 1, 0), axis=1)
        hit = cnt >= target
        hi = tl.where(hit, mid, hi)
        lo = tl.where(hit, lo, mid + 1)

    bits_low = tl.where(lo < 0, lo ^ 0x7FFFFFFF, lo)
    lower_values = bits_low.to(tl.float32, bitcast=True)
    # upper value = the smallest key strictly greater than lower_key (same as lower when rank is an integer),
    # a single masked-min replaces a second set of 32 binary-search rounds
    upper_key = tl.min(tl.where(valid & (keys > lo[:, None]), keys, 2147483647), axis=1)
    bits_up = tl.where(upper_key < 0, upper_key ^ 0x7FFFFFFF, upper_key)
    upper_values = tl.where(
        upper_rank == lower_rank, lower_values, bits_up.to(tl.float32, bitcast=True)
    )

    if interpolation == 0:
        result = lower_values + (upper_values - lower_values) * (
            ranks - lower_rank.to(tl.float32)
        )
    elif interpolation == 1:
        result = lower_values
    elif interpolation == 2:
        result = upper_values
    elif interpolation == 3:
        rounded = tl_extra_shim.rint(ranks).to(tl.int32)
        result = tl.where(rounded == upper_rank, upper_values, lower_values)
    else:
        result = lower_values + (upper_values - lower_values) * 0.5

    result = tl.where(valid_count == 0, float("nan"), result)
    tl.store(out + rows.to(tl.int64) * q_size + pair_qs, result, mask=pair_valid)


@libentry()
@triton.jit
def _validate_q_kernel(q, q_size, BLOCK_SIZE: tl.constexpr):
    offsets = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < q_size
    values = tl.load(q + offsets, mask=mask, other=0.0)
    valid = (~mask) | ((values >= 0.0) & (values <= 1.0))
    tl.device_assert(valid, "quantile() q values must be in the range [0, 1]")


def _heur_block_q(args):
    return triton.next_power_of_2(min(triton.cdiv(args["q_size"], 8), 16))


def _heur_block_n(args):
    n_rows = args["n_rows"]
    if n_rows >= 65536:
        return triton.next_power_of_2(triton.cdiv(n_rows, 512))
    if n_rows >= 4096:
        return triton.next_power_of_2(triton.cdiv(n_rows, 128))
    if n_rows >= 64:
        return 32
    if n_rows >= 32:
        return 4
    return 1


@libentry()
@triton.heuristics(values={"BLOCK_Q": _heur_block_q, "BLOCK_N": _heur_block_n})
@triton.jit
def _nanquantile_gather_kernel(
    sorted_inp,
    q,
    out,
    n_rows,
    reduction_size,
    q_size,
    BLOCK_Q: tl.constexpr,
    BLOCK_N: tl.constexpr,
    interpolation: tl.constexpr,
):
    q_offsets = ext.program_id(0) * BLOCK_Q + tl.arange(0, BLOCK_Q)
    compute_type = sorted_inp.dtype.element_ty
    row_offsets = ext.program_id(1) * BLOCK_N + tl.arange(0, BLOCK_N)
    valid_q = q_offsets < q_size
    valid_row = row_offsets < n_rows

    # CUDA sort places NaNs after all numeric values. Locate the first NaN in
    # each row without materializing a full-size mask or count tensor.
    low = tl.zeros((BLOCK_N,), dtype=tl.int64)
    high = tl.full((BLOCK_N,), reduction_size, dtype=tl.int64)
    # Searching an inclusive [0, 2**24] interval needs up to 25 steps.
    for _ in tl.static_range(25):
        middle = (low + high) // 2
        probe = tl.load(
            sorted_inp + row_offsets * reduction_size + middle,
            mask=valid_row & (middle < high),
            other=float("nan"),
        )
        probe_valid = probe == probe
        low = tl.where(probe_valid, middle + 1, low)
        high = tl.where(probe_valid, high, middle)
    counts_value = low
    all_nan = counts_value == 0
    last_valid = tl.maximum(counts_value - 1, 0).to(compute_type)
    q_values = tl.load(q + q_offsets, mask=valid_q, other=0.0).to(compute_type)
    ranks = last_valid[:, None] * q_values[None, :]
    lower = tl.floor(ranks).to(tl.int64)
    upper = tl.ceil(ranks).to(tl.int64)
    row_starts = row_offsets[:, None] * reduction_size
    lower_values = tl.load(
        sorted_inp + row_starts + lower,
        mask=valid_row[:, None] & valid_q[None, :],
        other=0.0,
    )
    upper_values = tl.load(
        sorted_inp + row_starts + upper,
        mask=valid_row[:, None] & valid_q[None, :],
        other=0.0,
    )

    if interpolation == 0:
        result = lower_values + (upper_values - lower_values) * (ranks - lower)
    elif interpolation == 1:
        result = lower_values
    elif interpolation == 2:
        result = upper_values
    elif interpolation == 3:
        rounded = tl_extra_shim.rint(ranks).to(tl.int64)
        result = tl.where(rounded == upper, upper_values, lower_values)
    else:
        result = lower_values + (upper_values - lower_values) * 0.5

    result = tl.where(all_nan[:, None], float("nan"), result)
    out_offsets = row_offsets[:, None] * q_size + q_offsets[None, :]
    tl.store(
        out + out_offsets,
        result,
        mask=valid_row[:, None] & valid_q[None, :],
    )


def _validate_args(inp, q, dim, interpolation, out):
    if inp.dtype not in (torch.float32, torch.float64):
        raise RuntimeError(
            "quantile() input tensor must be either float or double dtype"
        )
    if inp.numel() == 0:
        raise RuntimeError("quantile() input tensor must be non-empty")
    if interpolation not in INTERPOLATION_METHODS:
        raise RuntimeError(
            "quantile() interpolation must be one of linear, lower, higher, "
            f"midpoint or nearest, but got {interpolation}"
        )
    if dim is not None and not isinstance(dim, int):
        raise TypeError("quantile() dim must be an integer or None")
    if isinstance(q, torch.Tensor):
        if q.dim() > 1:
            raise RuntimeError("quantile() q must be a scalar or 1D tensor")
        if q.dtype != inp.dtype:
            raise RuntimeError(
                "quantile() q tensor must be same dtype as the input tensor"
            )
        if q.device != inp.device:
            raise RuntimeError(
                "quantile() q tensor must be on the same device as the input"
            )
    if out is not None:
        if out.dtype != inp.dtype:
            raise RuntimeError(
                "quantile() out tensor must be same dtype as the input tensor"
            )
        if out.device != inp.device:
            raise RuntimeError(
                "quantile() out tensor must be on the same device as the input"
            )


def _nanquantile_impl(
    inp, q, dim=None, keepdim=False, interpolation="linear", out=None
) -> Tensor:
    logger.debug("GEMS_ENFLAME NANQUANTILE")
    _validate_args(inp, q, dim, interpolation, out)

    original_ndim = inp.ndim
    dim_was_none = dim is None
    if dim_was_none:
        reduced = contiguous(inp).view(-1)
        dim = 0
    else:
        if inp.ndim == 0:
            if dim not in (-1, 0):
                raise IndexError("Dimension out of range")
            dim = 0
            reduced = inp.reshape(1)
        else:
            reduced = torch.movedim(inp, dim, -1)
            dim %= inp.ndim
            reduced = contiguous(reduced)

    q_is_tensor = isinstance(q, torch.Tensor)
    q_is_scalar = not q_is_tensor or q.dim() == 0
    q_value = None
    if not q_is_tensor:
        q_value = float(q)
        if not 0.0 <= q_value <= 1.0:
            raise RuntimeError(
                f"quantile() q must be in the range [0, 1] but got {q_value}"
            )
    if q_is_tensor:
        q_contiguous = contiguous(q).reshape(-1)
        if q_contiguous.numel():
            block_size = 256
            with torch_device_fn.device(inp.device):
                _validate_q_kernel[(triton.cdiv(q_contiguous.numel(), block_size),)](
                    q_contiguous,
                    q_contiguous.numel(),
                    BLOCK_SIZE=block_size,
                )
    else:
        # Defer tensor creation for a python float scalar q: the pairs path passes the scalar argument directly,
        # avoiding H2D;
        # only the bitonic / gather paths (which need a q pointer) materialize it here
        q_contiguous = None

    reduction_size = reduced.size(-1)
    if reduction_size > MAX_REDUCTION_SIZE:
        raise RuntimeError(
            "quantile() input tensor is too large; the reduction dimension "
            f"must not exceed {MAX_REDUCTION_SIZE} elements"
        )
    n_rows = reduced.numel() // reduction_size
    q_size = 1 if q_contiguous is None else q_contiguous.numel()
    internal_shape = (*reduced.shape[:-1], q_size)
    if q_is_scalar:
        result_shape = list(reduced.shape[:-1])
        if keepdim:
            if dim_was_none:
                result_shape = [1] * original_ndim
            else:
                result_shape.insert(dim, 1)
    else:
        result_shape = [q_size, *reduced.shape[:-1]]
        if keepdim:
            if dim_was_none:
                result_shape = [q_size, *([1] * original_ndim)]
            else:
                result_shape.insert(dim + 1, 1)
    direct_out = False
    if out is not None and q_is_scalar:
        out.resize_(result_shape)
        out_view = out.reshape(reduced.shape[:-1])
        if out_view.is_contiguous():
            internal = out_view.unsqueeze(-1)
            direct_out = True
        else:
            internal = torch.empty(internal_shape, dtype=inp.dtype, device=inp.device)
    elif out is not None and n_rows == 1:
        out.resize_(result_shape)
        if out.is_contiguous():
            internal = out.reshape(internal_shape)
            direct_out = True
        else:
            internal = torch.empty(internal_shape, dtype=inp.dtype, device=inp.device)
    else:
        internal = torch.empty(internal_shape, dtype=inp.dtype, device=inp.device)

    if q_size:
        if reduction_size:
            with torch_device_fn.device(inp.device):
                if (
                    inp.dtype == torch.float32
                    and (MIN_SELECT_SIZE if q_is_tensor else MIN_SELECT_SIZE_SCALAR)
                    <= reduction_size
                    <= MAX_SELECT_SIZE
                ):
                    # float32 uses the row-batch rank-selection path: (row, q) pairs are tiled row-major into the lane
                    # dimension,
                    # a single program's (BLOCK_R, BLOCK_M) counting matrix advances BLOCK_R independent binary
                    # searches,
                    # without relying on row count to fill the device (1D inputs also have only a few programs, but the
                    # per-program tax is fully amortized).
                    block_m = triton.next_power_of_2(reduction_size)
                    if block_m <= 256:
                        block_r = 8
                    elif block_m == 512:
                        block_r = 4
                    elif block_m == 1024:
                        block_r = 8
                    else:
                        block_r = 4
                    n_pairs = n_rows * q_size
                    # lane count does not exceed the number of pairs to process (otherwise 1D/few-row inputs waste empty
                    # lanes),
                    # a lower bound of 4 preserves the reduce parallelism shape of the (BLOCK_R, BLOCK_M) matrix
                    block_r = min(block_r, max(4, triton.next_power_of_2(n_pairs)))
                    _nanquantile_pairs_kernel[(triton.cdiv(n_pairs, block_r),)](
                        reduced,
                        q_contiguous if q_contiguous is not None else reduced,
                        internal,
                        n_pairs,
                        n_rows,
                        reduction_size,
                        q_size,
                        0.0 if q_value is None else q_value,
                        BLOCK_M=block_m,
                        BLOCK_R=block_r,
                        Q_SCALAR=q_value is not None,
                        interpolation=INTERPOLATION_CODES[interpolation],
                        num_warps=4,
                    )
                elif reduction_size <= MAX_BITONIC_SIZE:
                    if q_contiguous is None:
                        q_contiguous = torch.tensor(
                            q_value, dtype=inp.dtype, device=inp.device
                        ).reshape(-1)
                    block_m = triton.next_power_of_2(reduction_size)
                    block_q = min(triton.next_power_of_2(q_size), 16)
                    _nanquantile_bitonic_kernel[(n_rows, triton.cdiv(q_size, block_q))](
                        reduced,
                        q_contiguous,
                        internal,
                        reduction_size,
                        q_size,
                        BLOCK_M=block_m,
                        BLOCK_Q=block_q,
                        interpolation=INTERPOLATION_CODES[interpolation],
                        num_warps=min(16, max(8, block_m // 256)),
                    )
                else:
                    if q_contiguous is None:
                        q_contiguous = torch.tensor(
                            q_value, dtype=inp.dtype, device=inp.device
                        ).reshape(-1)
                    keys = torch.empty_like(reduced)
                    _sort_keys_kernel[(triton.cdiv(reduced.numel(), 1024),)](
                        reduced, keys, reduced.numel(), BLOCK_SIZE=1024
                    )
                    sorted_values, _ = sort_stable(
                        keys, stable=False, dim=-1, descending=False
                    )
                    grid = lambda meta: (
                        triton.cdiv(q_size, meta["BLOCK_Q"]),
                        triton.cdiv(n_rows, meta["BLOCK_N"]),
                    )
                    _nanquantile_gather_kernel[grid](
                        sorted_values,
                        q_contiguous,
                        internal,
                        n_rows,
                        reduction_size,
                        q_size,
                        interpolation=INTERPOLATION_CODES[interpolation],
                    )

    if q_is_scalar:
        result = internal.squeeze(-1)
    else:
        result = internal.movedim(-1, 0)
    if keepdim:
        result = result.reshape(result_shape)

    if out is not None:
        if direct_out:
            return out
        out.resize_(result.shape)
        copy_(out, result)
        return out
    return result


def nanquantile(inp, q, dim=None, keepdim=False, interpolation="linear") -> Tensor:
    logger.debug("GEMS_ENFLAME NANQUANTILE")
    logger.debug("GEMS_ENFLAME NANQUANTILE_SCALAR")
    logger.debug("GEMS_ENFLAME NANQUANTILE_OUT")
    logger.debug("GEMS_ENFLAME NANQUANTILE_SCALAR_OUT")
    return _nanquantile_impl(inp, q, dim, keepdim, interpolation)


def nanquantile_scalar(
    inp, q, dim=None, keepdim=False, interpolation="linear"
) -> Tensor:
    return _nanquantile_impl(inp, q, dim, keepdim, interpolation)


def nanquantile_out(
    inp, q, dim=None, keepdim=False, interpolation="linear", out=None
) -> Tensor:
    return _nanquantile_impl(inp, q, dim, keepdim, interpolation, out)


def nanquantile_scalar_out(
    inp, q, dim=None, keepdim=False, interpolation="linear", out=None
) -> Tensor:
    return _nanquantile_impl(inp, q, dim, keepdim, interpolation, out)
